          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P023 states the qualified priority inference without a numerical threshold; P031 and P027 supply the limits on causal conclusions."
    }
  },
  "signal_basis": {
    "component_id": "C033.signal_basis",
    "value": "Credible sources with independent access corroborate recurring timing or status sequences across bookings; comparison with timely bookings indicates whether similar patterns also occur without lateness.",
    "scope": "Evidence concerns the same equipment, booking and handoff. Dependence, poor access or unresolved contradictions can undermine a feature's established status.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
